-- Records of role_menu
-- ----------------------------

-- ----------------------------
-- Table structure for stock
-- ----------------------------
DROP TABLE IF EXISTS `stock`;
CREATE TABLE `stock`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '库存编号',
  `medicine_id` int UNSIGNED NOT NULL COMMENT '药品编号(外键)',
  `birthday` date NOT NULL COMMENT '有效日期',
  `price` decimal(10, 2) UNSIGNED NOT NULL COMMENT '药品单价',
  `count` int UNSIGNED NOT NULL COMMENT '库存数量',
  `version` int UNSIGNED NOT NULL COMMENT '库存版本',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `stock_medicine_id`(`medicine_id` ASC) USING BTREE,
  CONSTRAINT `stock_medicine_id` FOREIGN KEY (`medicine_id`) REFERENCES `medicine` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 403 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '药品库存信息表' ROW_FORMAT = DYNAMIC;

